const input = $json || {};
const source = (input.body && typeof input.body === 'object') ? input.body : input;
const cfg = $item(0).$node['Config'].json || {};

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') inQuotes = false;
      else cell += ch;
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') { }
      else cell += ch;
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

function rowsToObjects(rows) {
  if (!rows.length) return [];
  const headers = rows[0].map((h) => String(h || '').trim());
  const out = [];
  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const obj = {};
    headers.forEach((h, idx) => { if (h) obj[h] = r[idx] ?? ''; });
    const hasAny = Object.values(obj).some((v) => String(v || '').trim() !== '');
    if (hasAny) out.push(obj);
  }
  return out;
}

function nk(s){ return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); }
function pick(obj, aliases) {
  const wanted = new Set(aliases.map(nk));
  for (const [k, v] of Object.entries(obj || {})) {
    if (wanted.has(nk(k)) && String(v ?? '').trim() !== '') return String(v).trim();
  }
  return '';
}
function parseTags(tagStr, fallbackTag) {
  const src = String(tagStr || '').trim();
  const raw = src ? src : String(fallbackTag || '');
  return raw.split(',').map((t) => t.trim()).filter((t) => t.length > 0).filter((v, i, a) => a.indexOf(v) === i);
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, baseUrl, path, headers, body }) {
  const options = {
    method,
    url: `${String(baseUrl).replace(/\/$/, '')}${path}`,
    headers,
    json: true,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
    };
  }
}

let records = [];
if (Array.isArray(source.records)) {
  records = source.records;
} else if (typeof source.csvText === 'string' && source.csvText.trim() !== '') {
  records = rowsToObjects(parseCsv(source.csvText));
}
if (!records.length) throw new Error('Provide body.records (array) or body.csvText (CSV string)');

const dryRun = (source.dryRun === undefined || source.dryRun === null) ? !!cfg.defaultDryRun : !!source.dryRun;
const locationId = String(source.locationId || cfg.locationId || '').trim();
const apiBaseUrl = String(source.apiBaseUrl || cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').trim();
const apiKey = String(source.apiKey || cfg.apiKey || $env.GHL_PIT || '').trim();
const defaultTag = String(source.defaultTag || cfg.defaultTag || 'cold-outreach').trim();

if (!locationId) throw new Error('Missing locationId');
if (!dryRun && !apiKey) throw new Error('Missing apiKey (provide body.apiKey or set env GHL_PIT)');

const headers = {
  Authorization: `Bearer ${apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const results = [];
for (const rec of records) {
  const firstName = pick(rec, ['First Name','first_name','firstName']);
  const lastName = pick(rec, ['Last Name','last_name','lastName']);
  const email = pick(rec, ['Email','email']);
  const phone = pick(rec, ['Phone','phone','Mobile Phone','Corporate Phone','Work Direct Phone','Home Phone','Other Phone']);
  const companyName = pick(rec, ['Company Name','company_name','companyName']);
  const website = pick(rec, ['Website','website']);
  const city = pick(rec, ['City','city']);
  const state = pick(rec, ['State','state']);
  const country = pick(rec, ['Country','country']);
  const tags = parseTags(pick(rec, ['Tags','tags']), defaultTag);

  if (!email && !phone) {
    results.push({ status: 'skipped', reason: 'missing email and phone', firstName, lastName });
    continue;
  }

  if (dryRun) {
    results.push({ status: 'planned', email, phone, firstName, lastName, companyName, tags });
    continue;
  }

  const upsertBody = {
    locationId,
    firstName: firstName || undefined,
    lastName: lastName || undefined,
    email: email || undefined,
    phone: phone || undefined,
    companyName: companyName || undefined,
    website: website || undefined,
    city: city || undefined,
    state: state || undefined,
    country: country || undefined,
  };
  Object.keys(upsertBody).forEach((k) => upsertBody[k] === undefined && delete upsertBody[k]);

  const upsertRes = await apiRequest.call(this, {
    method: 'POST',
    baseUrl: apiBaseUrl,
    path: '/contacts/upsert',
    headers,
    body: upsertBody,
  });
  if (!upsertRes.ok) {
    results.push({ status: 'error', step: 'upsert', email, phone, details: upsertRes.data });
    continue;
  }

  const contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId;
  if (!contactId) {
    results.push({ status: 'error', step: 'resolve_contact_id', email, phone, details: upsertRes.data });
    continue;
  }

  let tagsResult = { ok: true };
  if (tags.length) {
    tagsResult = await apiRequest.call(this, {
      method: 'POST',
      baseUrl: apiBaseUrl,
      path: `/contacts/${contactId}/tags`,
      headers,
      body: { tags },
    });
  }

  if (!tagsResult.ok) {
    results.push({ status: 'error', step: 'tag_add', contactId, email, tags, details: tagsResult.data });
    continue;
  }

  results.push({ status: 'imported', contactId, email, phone, tagsAdded: tags.length });
}

return [{
  json: {
    ok: true,
    dryRun,
    locationId,
    sourceRecords: records.length,
    imported: results.filter((r) => r.status === 'imported').length,
    planned: results.filter((r) => r.status === 'planned').length,
    skipped: results.filter((r) => r.status === 'skipped').length,
    errors: results.filter((r) => r.status === 'error').length,
    results: results.slice(0, 200),
    note: dryRun ? 'No API writes executed. Set body.dryRun=false to run live.' : 'Live run executed.',
  },
}];

